    {
      "rec_id": "r1",
      "rationale": [
        {
          "text": "NIR transmission is preferred for transparent or semi-transparent liquids such as whey.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p18-nir-transmission-clear"]
        }
      ],
      "conditions": [
        {
          "text": "Quantitative NIR analysis needs chemometric calibration because its absorption bands overlap.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p10-nir-chemometrics"]
        }
      ],
      "limitations": []
    },
    {
      "rec_id": "r2",
      "rationale": [
        {
          "text": "In-line NIR reflection is used for opaque or highly concentrated dairy products, including milk concentrates.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p17-nir-reflection-opaque"]
        }
      ],
      "conditions": [],
      "limitations": [
        {
          "text": "NIR reflection is sensitive to surface characteristics and fat globule size.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p17-reflection-surface"]
        }
      ]
    },
    {
      "rec_id": "r3",
      "rationale": [
        {
          "text": "NIR diffuse-reflection probes are suited to scattering media.",
          "claim_type": "AFS",
          "evidence_ids": ["TABLE-nir_diffuse_reflection_probe"]
        }
      ],
      "conditions": [
        {
          "text": "Retain this option for whey only if the sample comparison demonstrates a usable diffuse-reflection signal.",
          "claim_type": "PROPOSAL",
          "evidence_ids": []
        }
      ],
      "limitations": []
    },
    {
      "rec_id": "r4",
      "rationale": [
        {
          "text": "A transflection probe can sometimes serve both low-fat and high-fat milk products.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p18-transflection-combined"]
        }
      ],
      "conditions": [
        {
          "text": "Retain this option for the concentrate only if sample tests demonstrate usable transmission or transflection spectra.",
          "claim_type": "PROPOSAL",
          "evidence_ids": []
        }
      ],
      "limitations": [
        {
          "text": "Transmission fails when milk becomes too thick or fat-rich for light to penetrate.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p18-transmission-fails-thick"]
        }
      ]
    }
  ],
  "premise_checks": [],
  "direct_answer": [
